        result = total_loss / total_weight
    except (OverflowError, ValueError, ZeroDivisionError) as exc:
        raise FloatingPointError(
            "non-finite value encountered during mean absolute "
            "percentage error"
        ) from exc
    if not math.isfinite(result):
        raise FloatingPointError(
            "non-finite value encountered during mean absolute "
            "percentage error"
        )
    if result == 0:
        result = 0.0
    return result


